    GUIDE_TRAVEL_ALLIANCE = "Vá a uma frente do Overlord no mundo aberto. Consulte o mapa para ver os pontos disponíveis e consulte o Próximo objetivo no painel lateral.",
    GUIDE_SECTION_SHARD = "Layers e sincronização",
